
'use client';

import { useEffect, useState } from 'react';
import { useSignIn, useClerk, useUser } from '@clerk/nextjs';
import {
  ArrowRight, BookOpen, Check, FileText, FolderOpen,
  Menu, Plus, ShieldCheck, UserRound
} from 'lucide-react';

type Project = {
  id: string;
  name: string;
  area: number;
  status: string;
  created: string;
  files: string[];
  owner: string;
  notes: string;
  report?: string;
};

const tiers = [
  { max: 300, label: 'Até 300 m²', price: 299 },
  { max: 500, label: '300 a 500 m²', price: 449 },
  { max: 1000, label: '500 a 1.000 m²', price: 699 }
];

const money = (n: number) =>
  n.toLocaleString('pt-BR', {
    style: 'currency',
    currency: 'BRL'
  });

const storage = 'ipl-demo-v2';

const requiredDocs = [
  'Projeto em PDF',
  'ART de projeto',
  'ART de execução',
  'ART de projeto da caixa de recarga',
  'ART de execução da caixa de recarga',
  'USO DO SOLO',
  'CERTIDÃO DE MATRÍCULA'
];

export default function Home() {
  const { user: clerkUser, isLoaded, isSignedIn } = useUser();
const { signOut, openSignUp, openSignIn } = useClerk();
const { signIn } = useSignIn();
const signInLoaded = signIn !== null && signIn !== undefined;
const { setActive } = useClerk();
  const [loginIdentifier, setLoginIdentifier] = useState('');
  const [loginPassword, setLoginPassword] = useState('');
  const [loginBusy, setLoginBusy] = useState(false);
  const [loginError, setLoginError] = useState('');

  const role =
    clerkUser?.publicMetadata?.role === 'tecnico'
      ? 'tecnico'
      : 'cliente';

  const user = isSignedIn && clerkUser
    ? {
        name:
          clerkUser.username ||
          clerkUser.firstName ||
          clerkUser.primaryEmailAddress?.emailAddress ||
          'Usuário',
        role
      }
    : null;

  const [screen, setScreen] = useState('home');
  const [error, setError] = useState('');
  const [projects, setProjects] = useState<Project[]>([]);
  const [sub, setSub] = useState(false);
  const [loadedStorage, setLoadedStorage] = useState(false);
  const [draft, setDraft] = useState({
    name: '',
    area: '',
    notes: ''
  });
  const [files, setFiles] = useState<Record<string, File | null>>({});
  const [selected, setSelected] = useState('');
  const [report, setReport] = useState('');
  const [evidence, setEvidence] = useState<File[]>([]);
  const [menu, setMenu] = useState(false);

  useEffect(() => {
    try {
      const v = JSON.parse(localStorage.getItem(storage) || '{}');
      setProjects(v.projects || []);
      setSub(!!v.sub);
    } catch {
      setProjects([]);
    } finally {
      setLoadedStorage(true);
    }
  }, []);

  useEffect(() => {
    if (!loadedStorage) return;
    localStorage.setItem(
      storage,
      JSON.stringify({ projects, sub })
    );
  }, [projects, sub, loadedStorage]);

  useEffect(() => {
    if (isLoaded && isSignedIn && screen === 'login') {
      setScreen('dashboard');
    }
  }, [isLoaded, isSignedIn, screen]);

  const tier = tiers.find(
    t => Number(draft.area) > 0 && Number(draft.area) <= t.max
  );

  const current = projects.find(
    p =>
      p.id === selected &&
      (user?.role === 'tecnico' || p.owner === user?.name)
  );

  const nav = (s: string) => {
    setScreen(s);
    setMenu(false);
    setError('');
  };

  function createProject() {
    if (!user || user.role !== 'cliente') return;

    const missing = requiredDocs.filter(d => !files[d]);

    if (!draft.name.trim() || !tier || missing.length) {
      setError(
        missing.length
          ? 'Anexe todos os sete documentos obrigatórios: ' +
              missing.join(', ')
          : 'Informe nome e área válida de até 1.000 m².'
      );
      return;
    }

    const p: Project = {
      id: 'IPL-' + Date.now().toString().slice(-8),
      name: draft.name,
      area: Number(draft.area),
      status: 'Solicitação recebida (teste)',
      created: new Date().toLocaleDateString('pt-BR'),
      owner: user.name,
      files: requiredDocs.map(
        d => d + ': ' + files[d]!.name
      ),
      notes: draft.notes
    };

    setProjects(v => [p, ...v]);
    setSelected(p.id);
    setDraft({ name: '', area: '', notes: '' });
    setFiles({});
    setError('');
    setScreen('dashboard');
  }

  function saveReport() {
    if (!current || user?.role !== 'tecnico') return;

    setProjects(v =>
      v.map(p =>
        p.id === current.id
          ? {
              ...p,
              report,
              status: 'Relatório demonstrativo salvo'
            }
          : p
      )
    );

    setError(
      'Relatório salvo neste navegador. Para entrega real, conecte o armazenamento compartilhado.'
    );
  }

  return (
    <>
      <header className="header">
        <div className="shell nav">
          <button className="brand" onClick={() => nav('home')}>
            <img
              className="brand-image"
              src="/logo-transparente.png"
              alt="Instituto Projeto Legal"
            />
          </button>

          <nav className={menu ? 'open' : ''}>
            <button onClick={() => nav('home')}>Início</button>
            <button onClick={() => nav('services')}>Serviços</button>
            <button onClick={() => nav('education')}>Educação</button>
            <button onClick={() => nav('how')}>Como funciona</button>
            {user && (
              <button onClick={() => nav('dashboard')}>
                Meu painel
              </button>
            )}
          </nav>

          <div className="nav-actions">
            {user ? (
              <button
                className="outline"
                onClick={() => {
                  void signOut();
                  nav('home');
                }}
              >
                Sair · {user.name}
              </button>
            ) : (
              <button
                className="outline"
                onClick={() => nav('login')}
              >
                <UserRound size={18} />
                Login
              </button>
            )}

            <button
              className="hamb"
              onClick={() => setMenu(!menu)}
              aria-label="Abrir menu"
            >
              <Menu />
            </button>
          </div>
        </div>
      </header>

      {screen === 'home' && (
        <>
          <section className="hero">
            <div className="shell hero-inner">
              <div className="hero-copy">
                <span className="eyebrow">
                  CONSULTORIA E EDUCAÇÃO
                </span>
                <h1>
                  Orientação técnica
                  <br />
                  para o seu projeto
                  <br />
                  <em>em Goiânia.</em>
                </h1>
                <p>
                  Orientação técnica independente e conhecimento
                  prático sobre a legislação urbana de Goiânia.
                </p>
                <div className="buttons">
                  <button
                    className="gold"
                    onClick={() => nav('services')}
                  >
                    Conheça os serviços
                    <ArrowRight size={18} />
                  </button>
                  <button
                    className="glass"
                    onClick={() => nav('how')}
                  >
                    Como funciona
                  </button>
                </div>
              </div>
              <div className="hero-art">
                <div className="art-label">
                  PROJETOS MAIS BEM ORIENTADOS.
                </div>
              </div>
            </div>
          </section>

          <section className="shell features">
            <div>
              <ShieldCheck />
              <span>
                <strong>Orientação independente</strong>
                <small>Clareza sobre os requisitos técnicos</small>
              </span>
            </div>
            <div>
              <BookOpen />
              <span>
                <strong>Aprendizado contínuo</strong>
                <small>Legislação explicada sem complicação</small>
              </span>
            </div>
            <div>
              <FileText />
              <span>
                <strong>Relatórios organizados</strong>
                <small>Registros e orientações em um só lugar</small>
              </span>
            </div>
          </section>

          <Services
            sub={sub}
            onChoose={() => {
              if (!user) nav('login');
              else if (user.role === 'cliente') nav('new');
              else nav('dashboard');
            }}
            onSubscribe={() => {
              if (!user) nav('login');
              else if (user.role === 'cliente') nav('billing');
              else nav('dashboard');
            }}
          />
          <How />
          <Education onClick={() => nav('education')} />
        </>
      )}

      {screen === 'services' && (
        <main className="shell page">
          <h1>Nossos serviços</h1>
          <p>
            Consultoria técnica orientativa para diferentes portes
            de projeto.
          </p>
          <Services
            sub={sub}
            onChoose={() => {
              if (!user) nav('login');
              else if (user.role === 'cliente') nav('new');
              else nav('dashboard');
            }}
            onSubscribe={() => {
              if (!user) nav('login');
              else if (user.role === 'cliente') nav('billing');
              else nav('dashboard');
            }}
          />
        </main>
      )}

      {screen === 'how' && (
        <main className="shell page">
          <How />
        </main>
      )}

      {screen === 'education' && (
        <main className="shell page">
          <span className="eyebrow dark">
            CONTEÚDO EDUCACIONAL
          </span>
          <h1>Aprenda no seu ritmo.</h1>
          <p>
            Módulos de estudo sobre legislação urbanística e
            edilícia. Conteúdo demonstrativo; aulas serão
            cadastradas pela equipe.
          </p>
          <div className="modules">
            {[
              'Recuos e afastamentos',
              'Taxa de ocupação',
              'Áreas computáveis',
              'Saliências acessórias',
              'Documentação técnica',
              'Acessibilidade'
            ].map((m, i) => (
              <div className="module" key={m}>
                <BookOpen />
                <small>
                  MÓDULO {String(i + 1).padStart(2, '0')}
                </small>
                <h3>{m}</h3>
                <p>Em preparação</p>
              </div>
            ))}
          </div>
        </main>
      )}

      {screen === 'login' && (
        <main className="login-page">
          <div className="shell login-shell">
            <div className="login-intro">
              <span className="eyebrow">
                ACESSO AO INSTITUTO
              </span>
              <h1>Bem-vindo de volta.</h1>
              <p>
                Entre com seu usuário e senha para acessar
                seu espaço.
              </p>
            </div>

            <div className="login-card" style={{ boxSizing: 'border-box', minWidth: 0 }}>
              <span className="eyebrow dark">ÁREA RESTRITA</span>
              <h2>Entrar na plataforma</h2>
              <div style={{ marginTop: 28, marginBottom: 8 }}>
  <button
    type="button"
    onClick={() => openSignIn()}
    style={{
      width: '100%',
      padding: '14px',
      background: '#ffffff',
      border: '1px solid #d5ddd8',
      borderRadius: 10,
      color: '#183b31',
      fontSize: 15,
      fontWeight: 600,
      cursor: 'pointer',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      gap: 12,
    }}
  >
    <span style={{ fontWeight: 800, fontSize: 20, color: '#4285F4' }}>
      G
    </span>
    Continuar com Google
  </button>

  <div
    style={{
      display: 'flex',
      alignItems: 'center',
      gap: 12,
      marginTop: 22,
      color: '#718078',
      fontSize: 13,
    }}
  >
    <div style={{ flex: 1, height: 1, background: '#dce3de' }} />
    ou entre com usuário e senha
    <div style={{ flex: 1, height: 1, background: '#dce3de' }} />
  </div>
</div>
              <form
                style={{ display: 'grid', gap: 18, marginTop: 28, width: '100%' }}
                onSubmit={async (event) => {
                  event.preventDefault();
                  setLoginError('');
                  if (!signInLoaded || !signIn || !setActive) {
                    setLoginError('A autenticação ainda está carregando. Tente novamente.');
                    return;
                  }
                  if (!loginIdentifier.trim() || !loginPassword) {
                    setLoginError('Informe seu usuário e sua senha.');
                    return;
                  }
                  setLoginBusy(true);
                  try {
               const { error } = await signIn.password({
  identifier: loginIdentifier.trim(),
  password: loginPassword,
});

if (error) {
  throw error;
}

if (signIn.status === 'complete' && signIn.createdSessionId) {
  await setActive({ session: signIn.createdSessionId });
  setLoginPassword('');
  nav('dashboard');
} else {
  setLoginError(
    'Este acesso requer uma etapa adicional de autenticação. Verifique sua conta.'
  );
}
                  } catch (err: unknown) {
                    const clerkError = err as { errors?: Array<{ longMessage?: string; message?: string }> };
                    setLoginError(clerkError?.errors?.[0]?.longMessage || clerkError?.errors?.[0]?.message || 'Não foi possível entrar. Confira suas credenciais.');
                  } finally {
                    setLoginBusy(false);
                  }
                }}
              >
                <label style={{ display: 'grid', gap: 8, fontWeight: 600 }}>
                  Usuário ou e-mail
                  <input
                    type="text"
                    autoComplete="username"
                    value={loginIdentifier}
                    onChange={event => setLoginIdentifier(event.target.value)}
                    placeholder="Digite seu usuário"
                    required
                    style={{ width: '100%', minWidth: 0, boxSizing: 'border-box', minHeight: 49, padding: '12px 14px', border: '1px solid #cad8d1', borderRadius: 10, background: '#fff', color: '#052f26', fontSize: 15 }}
                  />
                </label>
                <label style={{ display: 'grid', gap: 8, fontWeight: 600 }}>
                  Senha
                  <input
                    type="password"
                    autoComplete="current-password"
                    value={loginPassword}
                    onChange={event => setLoginPassword(event.target.value)}
                    placeholder="Digite sua senha"
                    required
                    style={{ width: '100%', minWidth: 0, boxSizing: 'border-box', minHeight: 49, padding: '12px 14px', border: '1px solid #cad8d1', borderRadius: 10, background: '#fff', color: '#052f26', fontSize: 15 }}
                  />
                </label>
                {loginError && <p role="alert" className="feedback">{loginError}</p>}
                <button
                  type="submit"
                  className="primary"
                  disabled={loginBusy || !signInLoaded}
                  style={{ width: '100%', justifyContent: 'center', minHeight: 49, background: '#07543f', color: '#fff', borderRadius: 10 }}
                >
                  {loginBusy ? 'Entrando...' : 'Acessar painel'}
                  <ArrowRight size={17} />
                </button>
              </form>
              <button
                type="button"
                onClick={() => openSignUp()}
                style={{ marginTop: 18, border: 0, background: 'transparent', color: '#07543f', cursor: 'pointer', textDecoration: 'underline' }}
              >
                Ainda não tem uma conta? Cadastre-se
              </button>
              <p className="login-note">
                Acesso protegido pelo Clerk. Os projetos ainda são armazenados apenas neste navegador, em modo demonstrativo.
              </p>
            </div>
          </div>
        </main>
      )}

      {screen === 'billing' && user?.role === 'cliente' && (
        <main className="shell page">
          <h1>Assinatura mensal</h1>
          <div className="panel narrow">
            <p>
              R$ 99,99/mês · acesso aos módulos educacionais ·
              30% de desconto em cada consultoria.
            </p>
            <div className="notice">
              Ambiente de demonstração. Este botão não cobra
              valores e não ativa uma assinatura comercial.
            </div>
            <button
              className="primary"
              onClick={() => {
                setSub(!sub);
                nav('dashboard');
              }}
            >
              {sub
                ? 'Desativar simulação de assinatura'
                : 'Simular assinatura ativa'}
            </button>
          </div>
        </main>
      )}

      {screen === 'dashboard' && user && (
        <main
          className={`shell page ${
            user.role === 'tecnico' ? 'dashboard-dark' : ''
          }`}
        >
          <div className="page-heading">
            <div>
              <span className="eyebrow dark">
                {user.role === 'tecnico'
                  ? 'PAINEL TÉCNICO'
                  : 'ÁREA DO CLIENTE'}
              </span>
              <h1>Olá, {user.name}.</h1>
              <p>
                {user.role === 'tecnico'
                  ? 'Acompanhe as solicitações e prepare relatórios.'
                  : 'Organize suas solicitações e acompanhe seus relatórios.'}
              </p>
            </div>

            {user.role === 'cliente' && (
              <button
                className="primary"
                onClick={() => nav('new')}
              >
                <Plus size={17} />
                Nova solicitação
              </button>
            )}
          </div>

          <div
            className={`stats ${
              user.role === 'tecnico' ? 'stats-tech' : ''
            }`}
          >
            <div>
              <small>Solicitações</small>
              <strong>
                {projects.filter(
                  p =>
                    user.role === 'tecnico' ||
                    p.owner === user.name
                ).length}
              </strong>
            </div>
            <div>
              <small>Relatórios</small>
              <strong>
                {projects.filter(
                  p =>
                    p.report &&
                    (user.role === 'tecnico' ||
                      p.owner === user.name)
                ).length}
              </strong>
            </div>
            {user.role === 'cliente' && (
              <div>
                <small>Assinatura (simulação)</small>
                <strong>{sub ? 'Ativa' : 'Inativa'}</strong>
              </div>
            )}
          </div>

          <div className="panel">
            <div className="panel-title">
              <h2>
                {user.role === 'tecnico'
                  ? 'Fila técnica'
                  : 'Meus projetos'}
              </h2>
              {user.role === 'cliente' && (
                <button
                  className="text-btn"
                  onClick={() => nav('billing')}
                >
                  Assinatura
                  <ArrowRight size={15} />
                </button>
              )}
            </div>

            {projects.filter(
              p =>
                user.role === 'tecnico' ||
                p.owner === user.name
            ).length === 0 ? (
              <div className="empty">
                <FolderOpen size={32} />
                <h3>Nenhuma solicitação ainda</h3>
                <p>
                  {user.role === 'tecnico'
                    ? 'Aguardando solicitações de clientes.'
                    : 'Cadastre um projeto para testar o fluxo.'}
                </p>
              </div>
            ) : (
              <div className="project-list">
                {projects
                  .filter(
                    p =>
                      user.role === 'tecnico' ||
                      p.owner === user.name
                  )
                  .map(p => (
                    <button
                      key={p.id}
                      onClick={() => {
                        setSelected(p.id);
                        setReport(p.report || '');
                        nav('detail');
                      }}
                    >
                      <div>
                        <strong>{p.name}</strong>
                        <small>
                          {p.id} · {p.area} m² · {p.created} ·
                          Cliente: {p.owner || 'Demo'}
                        </small>
                      </div>
                      <span className="status">{p.status}</span>
                      <ArrowRight size={17} />
                    </button>
                  ))}
              </div>
            )}
          </div>
        </main>
      )}

      {screen === 'new' && user?.role === 'cliente' && (
        <main className="shell page">
          <h1>Nova consultoria</h1>
          <p>
            Envie seus arquivos para uma orientação técnica
            independente.
          </p>

          <div className="panel form-panel">
            <label>
              Nome interno do projeto
              <input
                value={draft.name}
                onChange={e =>
                  setDraft({ ...draft, name: e.target.value })
                }
                placeholder="Ex.: Residência A"
              />
            </label>

            <label>
              Área construída (m²)
              <input
                type="number"
                min="1"
                max="1000"
                value={draft.area}
                onChange={e =>
                  setDraft({ ...draft, area: e.target.value })
                }
                placeholder="Ex.: 280"
              />
            </label>

            {tier ? (
              <div className="quote">
                <span>
                  Valor de referência
                  {sub ? ' (30% de desconto)' : ''}
                </span>
                <strong>
                  {money(tier.price * (sub ? 0.7 : 1))}
                </strong>
              </div>
            ) : (
              <div className="notice">
                Atendimento padronizado para projetos de
                até 1.000 m².
              </div>
            )}

            <label>
              Observações técnicas
              <textarea
                value={draft.notes}
                onChange={e =>
                  setDraft({ ...draft, notes: e.target.value })
                }
                rows={3}
                placeholder="Informações necessárias para contextualizar a consulta"
              />
            </label>

            <div className="document-list">
              <h3>Documentos obrigatórios</h3>
              <p>
                Adicione um PDF em cada campo antes de enviar
                a solicitação.
              </p>

              {requiredDocs.map((doc, i) => (
                <label key={doc} className="document-field">
                  <span>
                    <b>
                      {String(i + 1).padStart(2, '0')}.
                    </b>{' '}
                    {doc}
                    <span className="required"> *</span>
                  </span>
                  <input
                    type="file"
                    accept=".pdf,application/pdf"
                    onChange={e =>
                      setFiles(v => ({
                        ...v,
                        [doc]: e.target.files?.[0] || null
                      }))
                    }
                  />
                  {files[doc] && (
                    <small>
                      Selecionado: {files[doc]?.name}
                    </small>
                  )}
                </label>
              ))}
            </div>

            <div className="file-hint">
              Não informe número de processo administrativo.
              Evite inserir endereço, inscrição imobiliária ou
              outros identificadores desnecessários, preservando
              as informações técnicas exigidas para a orientação.
            </div>

            <div className="notice">
              Nesta demonstração, apenas os nomes dos arquivos
              são registrados localmente. Nenhum PDF é enviado
              ou armazenado em servidor. A cobrança real ficará
              bloqueada até a integração de pagamento.
            </div>

            {error && <p className="feedback">{error}</p>}

            <button
              className="primary"
              onClick={createProject}
            >
              Salvar solicitação de teste
              <ArrowRight size={17} />
            </button>
          </div>
        </main>
      )}

      {screen === 'detail' && current && user && (
        <main className="shell page">
          <button
            className="text-btn"
            onClick={() => nav('dashboard')}
          >
            ← Voltar ao painel
          </button>

          <div className="page-heading">
            <div>
              <span className="eyebrow dark">
                {current.id}
              </span>
              <h1>{current.name}</h1>
              <p>
                {current.area} m² · {current.status}
              </p>
            </div>
          </div>

          <div className="detail-grid">
            <div className="panel">
              <h2>Arquivos e informações</h2>
              <p>{current.notes || 'Sem observações.'}</p>
              {current.files.map(f => (
                <div className="file-row" key={f}>
                  <FileText size={17} />
                  {f}
                </div>
              ))}
              <div className="notice">
                Arquivos listados são somente uma demonstração,
                não podem ser abertos.
              </div>
            </div>

            <div className="panel">
              <h2>Relatório de orientação técnica</h2>

              {user.role === 'tecnico' ? (
                <>
                  <label>
                    Considerações, pendências e fundamentos
                    <textarea
                      rows={10}
                      value={report}
                      onChange={e =>
                        setReport(e.target.value)
                      }
                      placeholder="1. Tema / fundamento legal / orientação..."
                    />
                  </label>

                  <label>
                    Imagens de referência (demonstração)
                    <input
                      type="file"
                      accept="image/*"
                      multiple
                      onChange={e =>
                        setEvidence(
                          Array.from(e.target.files || [])
                        )
                      }
                    />
                  </label>

                  <small>
                    {evidence.map(f => f.name).join(', ') ||
                      'Nenhuma imagem selecionada'}
                  </small>

                  <div className="buttons">
                    <button
                      className="primary"
                      onClick={saveReport}
                    >
                      Salvar relatório
                    </button>
                    <button
                      className="outline dark-outline"
                      onClick={() => window.print()}
                    >
                      Imprimir / PDF
                    </button>
                  </div>
                </>
              ) : (
                <>
                  <p>
                    {current.report ||
                      'O relatório ainda não foi disponibilizado.'}
                  </p>
                  {current.report && (
                    <button
                      className="outline dark-outline"
                      onClick={() => window.print()}
                    >
                      Imprimir / PDF
                    </button>
                  )}
                </>
              )}

              {error && (
                <p className="feedback">{error}</p>
              )}
            </div>
          </div>
        </main>
      )}

      <footer>
        <div className="shell footer-inner">
          <div>
            <strong>Instituto Projeto Legal</strong>
            <small>
              Consultoria e educação em legislação urbana
            </small>
          </div>
          <p>
            Serviço privado e independente. Não representa
            aprovação ou manifestação oficial do Município.
          </p>
        </div>
      </footer>
    </>
  );
}

